from .unifier import unify

class DatalogEngine:
    def __init__(self):
        self.facts = set()

    def add_fact(self, *terms) -> None:
        self.facts.add(terms)

    def query(self, *pattern) -> list[dict]:
        res = []
        for f in sorted(self.facts):
            e = unify(pattern, f, {})
            if e is not None: res.append(e)
        return res

