def unify(pattern: tuple, fact: tuple, env: dict) -> dict | None:
    if len(pattern) != len(fact): return None
    res = dict(env)
    for p, f in zip(pattern, fact):
        if p.startswith('?'):
            if p in res and res[p] != f: return None
            res[p] = f
        elif p != f: return None
    return res

