import unittest
from datalog.engine import DatalogEngine

class TestDatalog(unittest.TestCase):
    def test_query(self):
        e = DatalogEngine()
        e.add_fact('edge', 'a', 'b')
        self.assertEqual(e.query('edge', '?x', 'b'), [{'?x': 'a'}])

if __name__ == '__main__': unittest.main()
